#!/usr/bin/env node
// Writes src/features/settings/privacyText.generated.ts: public/privacy.md as a string constant, so
// Settings › Privacy renders a bundled copy with no network request on every platform (a native
// build has no origin to fetch `/privacy.md` from). public/privacy.md stays the source and is still
// the public policy URL on the web.
//
//   node scripts/gen-privacy-text.mjs            (from app/) rewrites the generated file
//   node scripts/gen-privacy-text.mjs --check    exits 1 when the generated file is stale
//
// src/features/settings/__tests__/privacyText.test.ts fails when the two drift apart.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const APP_DIR = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(APP_DIR, 'public/privacy.md');
const OUTPUT = join(APP_DIR, 'src/features/settings/privacyText.generated.ts');

function render(markdown) {
  return [
    '// Generated by app/scripts/gen-privacy-text.mjs from app/public/privacy.md. Do not edit.',
    '// After changing public/privacy.md, run `node scripts/gen-privacy-text.mjs` from app/.',
    '',
    `export const PRIVACY_MARKDOWN = ${JSON.stringify(markdown)};`,
    '',
  ].join('\n');
}

const fresh = render(readFileSync(SOURCE, 'utf8'));
if (process.argv.includes('--check')) {
  let committed = '';
  try {
    committed = readFileSync(OUTPUT, 'utf8');
  } catch {
    // Missing counts as stale.
  }
  if (committed !== fresh) {
    console.error('privacyText.generated.ts is stale: run `node scripts/gen-privacy-text.mjs` from app/.');
    process.exit(1);
  }
} else {
  writeFileSync(OUTPUT, fresh);
  console.log('wrote src/features/settings/privacyText.generated.ts');
}
